from collections import Counter

def main():
    """Main interactive solution"""
    try:
        n_line = sys.stdin.readline()
        if not n_line.strip():
            sys.exit(0)
        n = int(n_line.strip())
    except:
        sys.exit(0)

    responses = []

    # Query 1: [1, n] - get all substrings
    print(f"? 1 {n}", flush=True)
    while True:
        rep = sys.stdin.readline()
        if not rep:
            break
        if rep.strip() == '-':
            sys.exit(0)
        responses.append(rep.strip().split())

    # Collect all single characters from all substring responses
    # Each response is a list of strings (substrings)
    all_chars = []
    for resp in responses:
        for substr in resp:
            all_chars.extend(substr)

    # Query 2: [1, n-1] if n > 1 to find last character
    if n > 1 and len(all_chars) > 0:
        print(f"? 1 {n-1}", flush=True)
        while True:
            rep = sys.stdin.readline()
            if not rep:
                break
            if rep.strip() == '-':
                sys.exit(0)
            responses.append(rep.strip().split())
            all_chars.extend(''.join(rep))

    # Query 3: [1, 1] to get first character (if needed)
    if sys.version_info >= (3, 0) and n > 0:
        # Third query for first character info
        print(f"? 1 1", flush=True)
        while True:
            rep = sys.stdin.readline()
            if not rep:
                break
            if rep.strip() == '-':
                sys.exit(0)
            responses.append(rep.strip().split())

    # Count character frequencies
    counter = Counter(all_chars)

    # For the output, use a simple strategy
    if n == 1:
        print("! " + list(counter.keys()).pop() if counter else "! a", flush=True)
    elif n > 0:
        # Guess based on most common character * n
        chars = list(counter.items())
        if chars:
            most_common = chars[0][0]
            print(f"! {most_common}{' ' * n}", flush=True)
        else:
            print(f"! {'a'*n}", flush=True)

