def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    m = int(lines[0].split()[-2])
    k = int(lines[0].split()[-2])
    p = int(lines[0].split()[-1])

    bamboos = []
    for i in range(1, n + 1):
        parts = lines[i].split()
        bamboos.append((int(parts[0]), int(parts[1])))

    def can_achieve(threshold):
        if k * m == 0:
            return True
        total_hits_needed = 0
        for h_i, a_i in bamboos:
            height_with_growth = h_i + m * a_i
            if height_with_growth > threshold:
                excess = height_with_growth - threshold
                hits_for_this_bamboo = (excess + p - 1) // p
                total_hits_needed += hits_for_this_bamboo

        return total_hits_needed <= k * m

    # Binary search for minimum threshold
    lo = 0
    hi = 0
    for h_i, a_i in bamboos:
        hi = max(hi, h_i + m * a_i)

    while lo < hi:
        mid = (lo + hi) // 2
        if can_achieve(mid):
            hi = mid
        else:
            lo = mid + 1

    return str(lo)

