def solution(input_str):
    # Parse n and tree edges
    lines = input_str.strip().split('\n')
    n = int(lines[0])

    MOD = 1000000007

    # We don't actually need the edge list - all labeled trees on n vertices
    # are counted the same way. The formula is structural.

    # Precompute binomial coefficients
    def binom(n_val, k_val):
        if k_val < 0 or k_val > n_val:
            return 0
        if k_val == 0 or k_val == n_val:
            return 1
        if k_val > n_val // 2:
            k_val = n_val - k_val
        result = 1
        for i in range(k_val):
            result = result * (n_val - i) // (i + 1)
        return result

    # Precompute powers of n
    powers = [1] * (n + 5)
    for i in range(1, n + 5):
        powers[i] = (powers[i-1] * n) % MOD

    results = []

    for k in range(n):
        total = 0
        for j in range(k, n):
            sign = 1 if (j - k) % 2 == 0 else -1

            # Term = C(j,k) * C(n-1,j) * n^max(0, n-j-2)
            term_const = binom(j, k) * binom(n - 1, j)

            if n - j - 2 < 0:
                # j = n-1, only 1 tree contains all n-1 edges
                exponent = 0
            else:
                exponent = n - j - 2

            term = (term_const * powers[exponent]) % MOD

            if sign == 1:
                total = (total + term) % MOD
            else:
                total = (total - term + MOD) % MOD

        results.append(str(total))

    return ' '.join(results)


