def binom_mod(n, k, mod=1000000007):
    if k < 0 or k > n:
        return 0
    if k == 0 or k == n:
        return 1
    k = min(k, n - k)
    numerator = 1
    for i in range(k):
        numerator = (numerator * (n - i)) % mod
    denominator = 1
    for i in range(1, k + 1):
        denominator = (denominator * i) % mod
    return (numerator * pow(denominator, mod - 2, mod)) % mod


