def grundy(n, k, memo):
    if n in memo:
        return memo[n]

    if n == 0:
        result = 0
    else:
        reachable = set()
        if n % 2 == 1:
            # Odd number pile: can only remove 1 cow
            reachable.add(grundy(n - 1, k, memo))
        else:
            # Even number pile: can remove 1 cow or split
            reachable.add(grundy(n - 1, k, memo))
            if k % 2 == 1:
                # k is odd: splitting creates k piles of size n/2
                # XOR of k copies of grundy(n/2) is grundy(n/2) when k is odd
                reachable.add(grundy(n // 2, k, memo))
            else:
                # k is even: XOR of k copies is 0
                reachable.add(0)

        # Compute MEX (Minimum EXcluded value)
        mex = 0
        while mex in reachable:
            mex += 1
        result = mex

    memo[n] = result
    return result

