def solve_brute(a, b, n):
    s = list("abcdefg")[:a]
    pos = 0
    while pos < n:
        # Mister B
        for _ in range(b):
            s.append('z')
        pos += b
        if pos >= n:
            return ''.join(s)
        # Computer
        # Get suffix of length a
        suffix = s[-a:]
        # Find characters not in suffix
        used = set(suffix)
        avail = [chr(ord('a') + i) for i in range(26) if chr(ord('a') + i) not in used]
        t = ''.join(avail)[:a]
        s.extend(t)
        pos += a
    return ''.join(s)

