import math

def solution(input_str):
    def is_prime(n):
        """Check if n is prime using trial division for efficiency on small n."""
        if n < 2:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False

        # For numbers up to 3e8, we can use simple trial division up to sqrt(n)
        # This is efficient enough when checked only for n ≡ 1 (mod 4) or n = 2
        limit = int(math.isqrt(n))
        for i in range(3, limit + 1, 2):
            if n % i == 0:
                return False
        return True

    def has_two_squares_sum(n):
        """
        A prime p can be written as sum of two squares iff:
        p = 2 or p ≡ 1 (mod 4)

        Since a = b = 1 gives 2 = 1² + 1² (both positive), 2 works.
        For primes ≡ 1 (mod 4), both squares must be positive since
        if one were 0, the prime would need to be a perfect square.
        """
        return n == 2 or n % 4 == 1

    try:
        line = input_str.strip()
        if not line:
            return "0\n"
        parts = line.split()
        l, r = int(parts[0]), int(parts[1])
    except:
        return "0\n"

    count = 0

    # Simplify: only check numbers ≡ 1 (mod 4) or n = 2
    # For each candidate, check primality
    for i in range(max(1, l), r + 1):
        if i == 2 or i % 4 == 1:
            if is_prime(i):
                count += 1

    return str(count) + '\n'


