def solution(input_string):
    lines = input_string.strip().split('\n')
    n = int(lines[0])
    points = []
    for i in range(1, n + 1):
        x, y = map(int, lines[i].split())
        points.append((x, y))

    MOD = 10**9 + 7

    def cross_product(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    def is_diagonal_valid(i, j):
        """Check if diagonal (i, j) is valid for triangulation"""
        if abs(i - j) == 1 or (i == 0 and j == n - 1):
            return True  # It's a polygon edge

        p_i, p_j = points[i], points[j]

        for k in range(n):
            next_k = (k + 1) % n
            # Skip edges that touch diagonal endpoints
            if next_k == i or next_k == j or k == i or k == j:
                continue

            p_k, p_next = points[k], points[next_k]

            c1 = cross_product(p_i, p_j, p_k)
            c2 = cross_product(p_i, p_j, p_next)

            # If the diagonal and edge cross each other
            if c1 * c2 < 0:
                # Check if they're on opposite sides of each other
                c3 = cross_product(p_k, p_next, p_i)
                c4 = cross_product(p_k, p_next, p_j)
                if c3 * c4 < 0:
                    return False

        return True

    # dp[i][j] = number of triangulations of subpolygon from vertex i to vertex j
    dp = [[0] * n for _ in range(n)]

    # Initialize base cases
    for i in range(n):
        dp[i][i] = 1  # Single vertex
        if i < n - 1:
            dp[i][i + 1] = 1  # Two adjacent vertices form one edge

    # Fill DP table by increasing length of subpolygon
    for length in range(2, n):  # number of edges in subpolygon from i to j-1
        for i in range(n):
            j = i + length
            if j >= n:
                continue

            # Base case: if length is such that it's a triangle (only 1 way)
            if length == 2:
                dp[i][j] = 1
                continue

            count = 0
            # Try all possible third vertices k for triangle (i, k, j)
            for k in range(i + 1, j):
                # Check if (i, k) and (k, j) are valid diagonals
                if is_diagonal_valid(i, k) and is_diagonal_valid(k, j):
                    count = (count + dp[i][k] * dp[k][j]) % MOD

            dp[i][j] = count

    return str(dp[0][n - 1]) + '\n'

