    shapes = [
        {(0, 0), (0, 1), (0, 2), (1, 1), (2, 1)},  # Shape 1
        {(0, 2), (1, 0), (1, 1), (1, 2), (2, 2)},  # Shape 2
        {(0, 1), (1, 2), (2, 0), (2, 1), (2, 2)},  # Shape 3
        {(0, 0), (1, 0), (1, 1), (1, 2), (2, 0)},  # Shape 4
    ]

    grid = [[None for _ in range(m)] for _ in range(n)]
    best_solution = {'count': 0, 'grid': None}

    def find_first_empty():
        for r in range(n):
            for c in range(m):
                if grid[r][c] is None:
                    return (r, c)
        return None

    def can_place(shape, anchor_r, anchor_c):
        for dr, dc in shape:
            r, c = anchor_r + dr, anchor_c + dc
            if r < 0 or r >= n or c < 0 or c >= m or grid[r][c] is not None:
                return False
        return True

    def place_shape(shape, anchor_r, anchor_c, letter):
        for dr, dc in shape:
            grid[anchor_r + dr][anchor_c + dc] = letter

    def remove_shape(shape, anchor_r, anchor_c):
        for dr, dc in shape:
            grid[anchor_r + dr][anchor_c + dc] = None

    def backtrack(square_count):
        if square_count >= best_solution['count']:
            # Try to improve or update if same count
            pass

        first_empty = find_first_empty()
        if first_empty is None:
            if square_count > best_solution['count']:
                best_solution['count'] = square_count
                best_solution['grid'] = [row[:] for row in grid]
            return

        r, c = first_empty

        # Try each placement that covers (r,c)
        for shape_idx in range(4):
            shape = shapes[shape_idx]
            # Generate all possible anchor positions (bounding box top-left)
            for pr in range(-2, n):
                for pc in range(-2, m):
                    # Check if this placement would cover (r,c)
                    covers_rc = False
                    for dr, dc in shape:
                        if pr + dr == r and pc + dc == c:
                            covers_rc = True
                            break

                    if not covers_rc:
                        continue

                    if can_place(shape, pr, pc):
                        letter = chr(ord('A') + square_count)
                        place_shape(shape, pr, pc, letter)

                        # Update best solution if we found a better or equal with more plows
                        updated = False
                        if square_count > best_solution['count']:
                            best_solution['count'] = square_count
                            best_solution['grid'] = [row[:] for row in grid]
                            updated = True

                        backtrack(square_count + 1)

                        remove_shape(shape, pr, pc)

        if square_count >= best_solution['count']:
            # Check if we've completed this branch
            if first_empty is None:
                if square_count > best_solution['count']:
                    best_solution['count'] = square_count
                    best_solution['grid'] = [row[:] for row in grid]

    # Start backtracking
    backtrack(0)

    result_lines = [str(best_solution['count'])]
