                    if sqrt_d * sqrt_d == d:
                        perfect_sq_count += 1

            total += max_c

        total_with_larger = 0
        if LIMIT < n:
            for b in range(LIMIT + 1, n + 1):
                max_c = m

                count_perfect = m
                for c in range(1, max_c + 1):
                    d = b * b - c
                    if d > 0:
                        sqrt_d = int(d ** 0.5)
                        if sqrt_d * sqrt_d == d:
                            count_perfect -= 1
                            total_with_larger += count_perfect
                            break
                if not count_perfect:
                    total_with_larger += m

        for b in range(1, n + 1):
            max_c = min(b * b, m)
            perfect_sq = 0
