def is_complete_binary_tree(n, adj, num_vertices):
    """Check if adj forms a complete full binary tree of n-1 height"""
    if not adj:
        return False

    # BFS to count nodes and check structure
    visited = set()
    queue = [1]
    visited.add(1)

    expected_nodes = 2**n - 1

    # Check all nodes connect
    while queue:
        node = queue.pop(0)

        if node not in adj:
            continue

        for neighbor in adj.get(node, []):
            if neighbor not in visited and 0 < neighbor < num_vertices + 1:
                visited.add(neighbor)
                queue.append(neighbor)

    return len(visited) == expected_nodes and is_perfect_binary(adj, 1, 0, n - 1)

def is_perfect_binary(adj, node, depth, max_height):
    """Check if subtree from node with given depth is perfect binary tree"""
    if depth >= max_height:
        return True

    if node not in adj or len(adj.get(node, [])) != 2:
        return False

    left_child = None
    right_child = None

    for neighbor in adj.get(node, []):
        if neighbor < node:
            left_child = neighbor
        else:
            right_child = neighbor

    if left_child is None or right_child is None:
        return False

    return is_perfect_binary(adj, left_child, depth + 1, max_height) and \
           is_perfect_binary(adj, right_child, depth + 1, max_height)

