            return memo[state]

        can_force_w = False

        # Option 1: Increase boxes
        # Check if the new state would still be below threshold
        if (curr_a + 1) ** curr_b < n:
            # If opponent loses from this new state, then current position is winning
            if not dfs(curr_a + 1, curr_b):
                can_force_w = True

        # Option 2: Increase items (only if we haven't already found a winning move)
        if not can_force_w and curr_a ** (curr_b + 1) < n:
            if not dfs(curr_a, curr_b + 1):
                can_force_w = True

        memo[state] = can_force_w
        return can_force_w

    # If Stas (first player) can force a win, output Stas, otherwise Masha
