def solution(input_str: str) -> str:
    lines = input_str.strip().split('\n')
    n, k = map(int, lines[0].split())

    phones = []
    all_prefixes = set()

    for i in range(1, n + 1):
        parts = lines[i].split()
        s, m = parts[0], int(parts[1])
        phones.append((s, m))
        # Generate all prefixes of this phone number
        for j in range(1, len(s) + 1):
            all_prefixes.add(s[:j])

    prefixes = sorted(all_prefixes)
    num_prefixes = len(prefixes)

    def compute_cost(selected: List[str]) -> int:
        """Calculate total digit presses given selected speed dial prefixes."""
        total_saved = 0
        for s, m in phones:
            # Find the longest matching prefix from selection
            max_len = 0
            for p in selected:
                if s.startswith(p):
                    max_len = max(max_len, len(p))
            # Cost is remaining digits * frequency
            total_saved += m * (len(s) - max_len)
        return total_saved

    # For small number of prefixes, try exhaustive search
    if num_prefixes <= 27 or k <= 3:
        best_cost = float('inf')
        for combo in itertools.combinations(prefixes, k):
            cost = compute_cost(list(combo))
            best_cost = min(best_cost, cost)
        return str(best_cost)

    # For larger cases, use greedy selection
    selected = []
    remaining = list(prefixes)

    for _ in range(k):
        best_gain = -1
        best_p = None

        for p in remaining:
            gain = 0
            for s, m in phones:
                # Find current best match with already selected prefixes
                current_max = 0
                for sp in selected:
                    if s.startswith(sp):
                        current_max = max(current_max, len(sp))

                # If we add prefix p, what's the new best match?
                new_max = len(p) if s.startswith(p) else 0
                if new_max > current_max:
                    gain += m * (new_max - current_max)

            if gain > best_gain:
                best_gain = gain
                best_p = p

        if best_p:
            selected.append(best_p)
            remaining.remove(best_p)

    return str(compute_cost(selected))

