            for ch in num_str:
                mod_result = (mod_result * 10 + int(ch)) % MOD
            return mod_result, len(num_str)

        elif peek() == '(':
            consume()
            sub_mod, sub_len = eval_expr()
            consume()  # ')'
            repeat_times = read_number()

            mod_result = 0
            for _ in range(repeat_times):
                mod_result = (mod_result * pow(10, sub_len, MOD) + sub_mod) % MOD

            return mod_result, sub_len * repeat_times

        return left, len(str(left))

    def eval_expr():
        left_mod, left_len = eval_term()

        while peek() == '+':
            consume()
            right_mod, right_len = eval_term()

            left_mod = (left_mod * pow(10, right_len, MOD) + right_mod) % MOD
            left_len += right_len

        return left_mod, left_len

    result_mod, _ = eval_expr()
    return str(result_mod)

