def solve_bfs(n):
    """BFS to find minimum steps from n to 0"""
    if n == 0:
        return 0

    visited = set()
    queue = deque([n])
    visited.add(n)
    steps = 0

    while queue:
        layer_size = len(queue)
        for _ in range(layer_size):
            current = queue.popleft()
            s = str(current)
            n_digits = set(int(c) for c in s)

            for d in n_digits:
                if d == 0:
                    continue
                next_val = current - d
                if next_val == 0:
                    return steps + 1
                if next_val not in visited:
                    visited.add(next_val)
                    queue.append(next_val)
        steps += 1

    return -1

