    # For larger numbers, use BFS with aggressive pruning
    # We need to be careful about memory

    if n > 10**17:
        # Use a more memory-efficient BFS
        memo = {n: 0}
        queue = deque([n])
        steps = 0

        while queue:
            layer_size = len(queue)
            for _ in range(layer_size):
                current = queue.popleft()

                # Get unique digits
                s = str(current)
                unique_digits = {}
                for c in s:
                    d = int(c)
                    if d not in unique_digits:
                        unique_digits[d] = True
                    if d == 0:
                        continue

                for d in unique_digits:
                    next_val = current - d
                    if next_val == 0:
                        return str(steps + 1) + "\n"

                    if next_val not in queue and next_val not in memo and next_val > 0:
                        memo[next_val] = memo[current] + 1
                        queue.append(next_val)
            steps += 1

        return str(memo.get(n, steps)) + "\n"
    else:
        return str(solve_bfs(n)) + "\n"

