    MOD = 1000000007

    if k == 0:
        return '1\n'

    n = k + 1  # Elements are 0, 1, ..., k

    count = 0

    # Enumerate all possible subsets using bitmasks
    for mask in range(1, 1 << n):
        S = [i for i in range(n) if mask & (1 << i)]
        S_set = set(S)

        # Must contain 0
        if 0 not in S_set:
            continue

        # Check XOR closure
        is_perfect = True
        for a in S:
            for b in S:
                if (a ^ b) not in S_set:
                    is_perfect = False
                    break
            if not is_perfect:
                break

        if is_perfect:
            count += 1

    return str(count % MOD) + '\n'

